+		}
+		err := json.NewDecoder(resp.Body).Decode(&parsed)
+		resp.Body.Close()
+		if err != nil {
+			t.Fatal(err)
+		}
+		if len(parsed.Ideas) == 0 {
+			t.Fatal("generation returned no ideas")
+		}
+		for _, idea := range parsed.Ideas {
